// ── OCI IAM Policy Catalog ────────────────────────────────────────────────────
// Oracle Cloud Infrastructure — common policy group patterns
// Verb model: inspect < read < use < manage

export type OciTier     = 'Manage' | 'Use' | 'Read' | 'Inspect'
export type OciCategory = 'Identity' | 'Compute' | 'Storage' | 'Networking' | 'Database' | 'Security' | 'DevOps' | 'Containers' | 'Serverless' | 'Messaging' | 'Analytics' | 'Monitoring' | 'AI' | 'Billing' | 'Management'

export interface OciTierMeta {
  label: string
  color: string
  bg: string
  description: string
}

export interface OciPolicy {
  slug: string
  name: string
  description: string
  tier: OciTier
  category: OciCategory
  isPrivileged: boolean
  scope: 'tenancy' | 'compartment' | 'resource'
  resourceTypes: string[]
  privileges: string[]
  exampleStatement: string
  verbActions?: string[]
}

export const OCI_TIER_META: Record<OciTier, OciTierMeta> = {
  Manage:  { label: 'Manage',  color: '#dc2626', bg: '#dc262618', description: 'Full CRUD — create, read, update, delete and administer the resource.' },
  Use:     { label: 'Use',     color: '#ea580c', bg: '#ea580c18', description: 'Work with existing resources without create/delete at the top-level resource.' },
  Read:    { label: 'Read',    color: '#16a34a', bg: '#16a34a18', description: 'View all resource details including sensitive configuration and credentials.' },
  Inspect: { label: 'Inspect', color: '#0891b2', bg: '#0891b218', description: 'List resources and view basic metadata — no sensitive data access.' },
}

